import numpy as np

# Function to safely extract features from a generator
def safe_predict(model, generator, max_attempts=3):
    features_list = []
    for attempt in range(max_attempts):
        try:
            features_list.append(model.predict(generator, steps=len(generator)))
            break
        except Exception as e:
            if attempt < max_attempts - 1:
                print(f"Attempt {attempt + 1} failed: {e}. Retrying...")
                # Reset the generator
                generator.reset()
            else:
                print(f"All attempts failed. Using partial results.")
                # Try processing batch by batch
                generator.reset()
                for batch_num in range(len(generator)):
                    try:
                        batch_features = model.predict(generator, steps=1)
                        if len(features_list) == 0:
                            features_list.append(batch_features)
                        else:
                            features_list[0] = np.vstack([features_list[0], batch_features])
                    except:
                        continue
                break

    if len(features_list) == 0:
        raise RuntimeError("Failed to extract any features")
    elif len(features_list) == 1:
        return features_list[0]
    else:
        # Concatenate multiple attempts (if some succeeded partially)
        return np.concatenate(features_list[:len(generator.samples) // generator.batch_size + 1], axis=0)[:len(generator.classes)]

